 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.input_30_onclick = async function(e){
    try {
        await scwin.removeJohang()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf72010.input_30_onclick' }); }
};

/**
 * @method
