///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name insertRelLaw
 * @description insert Rel Law 처리
 * @param {String} relLawDtlNm relLawDtlNm
 * @param {*} relLawDtlNo relLawDtlNo
 * @param {*} sprtRoomNo sprtRoomNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insertRelLaw = async function (relLawDtlNm, relLawDtlNo, sprtRoomNo) {
    if (!await $c.win.confirm("단위조항을 적용하시겠습니까?")) {
        return;
    }
    let chrgInstId = $('#junmoon option:selected').val();
    chrgInstId = chrgInstId.split("_")[1];
    $c.util.getComponent('slc_junmoon').setValue(sprtRoomNo + "_KRX");
    (($c.util.getComponent('slc_junmoon')) && ($c.util.getComponent('slc_junmoon')).setDisabled ? ($c.util.getComponent('slc_junmoon')).setDisabled((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
    $c.util.getComponent('ipt_relLawDtlNo').setValue(relLawDtlNo);
    $c.util.getComponent('ipt_johang').setValue(relLawDtlNm);
    setBtnEnable($('#removeSpan'));
};

/**
 * @method
 * @name removeJohang
 * @description remove Johang 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.removeJohang = async function () {
    if ($('#removeSpan').hasClass("bt2")) {
        return;
    }
    if (!await $c.win.confirm("단위조항을 제거하시겠습니까?")) {
        return;
    }
    $c.util.getComponent('ipt_relLawDtlNo').setValue("");
    $c.util.getComponent('ipt_johang').setValue("");
    $c.util.getComponent('slc_junmoon').setValue("");
    $c.util.getComponent('slc_junmoon').setDisabled(false);
    setBtnDisable($('#removeSpan'));
};

/**
 * @method
 * @name changeBubJohang
 * @description change Bub Johang 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeBubJohang = function () {
    $c.util.getComponent('ipt_dupChkYn').setValue("");
    if ($('#dupBtn').hasClass("bt2")) {
        setBtnEnable($('#dupBtn'));
    }
};

/**
 * @method
 * @name saveBubJohang
 * @description save Bub Johang 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveBubJohang = async function () {
    if ($c.util.getComponent('ipt_dupChkYn').getValue() === 'Y') {
        let sprtRoomNo = $('#junmoon option:selected').val();
        sprtRoomNo = sprtRoomNo.split("_")[0];
        let chrgInstId = $('#junmoon option:selected').val();
        chrgInstId = chrgInstId.split("_")[1];
        const relLawDtlNm = $c.util.getComponent('ipt_bubjohang').getValue();
        let relLawDtlNo = $c.util.getComponent('ipt_relLawDtlNo').getValue(); if (relLawDtlNo == null) { relLawDtlNo = ''; }
        let junmoon = $c.util.getComponent('slc_junmoon').getValue(); if (junmoon == null) { junmoon = ''; }
        if (junmoon === '') {
            await $c.win.alert("법규전문을 선택해 주세요.");
            return;
        }
        if (chrgInstId === "KRX" && relLawDtlNo === "") {
            await $c.win.alert("한국거래소 법규전문일 경우에는 단위조항을 선택해야 합니다.");
            return;
        }
        if (await $c.win.confirm("저장하시겠습니까?")) {
            $c.util.getComponent('ipt_method').setValue("insertRelLaw");
            $c.util.getComponent('ipt_relLawDtlNo').setValue(relLawDtlNo);
            $c.util.getComponent('ipt_relLawDtlNm').setValue(relLawDtlNm);
            $c.util.getComponent('ipt_sprtRoomNo').setValue(sprtRoomNo);
            await scwin.tx_fn_saveBubJohang();
        }
    } else {
        await $c.win.alert("관련법규 조항 중복확인 후 등록가능합니다.");
    }
};

/**
 * @method
 * @name closeFrame
 * @description close Frame 처리
 * @returns {void}
 * @hidden N
 */
scwin.closeFrame = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
    $c.win.closePopup();
};
// [A] 초기 목록 미해결 — 진입 키 integsrchbase 를 쓰는 tx 가 4개다(tx_fn_saveBubJohang, tx_fn_searchBubJohang, tx_fn_showDetail, tx_fn_chkDup)

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
